import path from 'node:path';

import { omcIdentifier, omcValidate } from 'omc-util';

import '../types.js'; // Type definitions, resolved globally by JSDoc

/** camelCase file name for an entity type: ProductionScene -> productionScene.json */
const fileFor = (entityType) => `${entityType.charAt(0).toLowerCase()}${entityType.slice(1)}.json`;

/**
 * Validate every entity individually.
 *
 * `omcValidate` defaults to atomic, which collapses the whole set to a single boolean. That
 * is useless for a report — run it non-atomically so a failure names the entity and the
 * offending property.
 *
 * @memberof namespace:DataPipeline
 * @function validateEntities
 * @param {Array<OmcEntity>} entities - Entities to check
 * @returns {DataPipeline.ValidationResult} Result, with per-entity failures
 */
export function validateEntities(entities) {
    const results = omcValidate(entities, { atomic: false });
    const failures = results
        .filter((r) => !r.valid)
        .map((r) => ({
            entityType: r.omcEntity?.entityType,
            // One identifier at a time: idCombinedForm takes a single identifier, and handing it
            // the array produced "undefined/undefined" — so a failed build named no entity at all.
            identifier: (r.omcEntity?.identifier ?? [])
                .map((id) => omcIdentifier.idCombinedForm(id, '/'))
                .join(', '),
            errors: (r.error ?? []).map((e) => `${e.instancePath || '/'} ${e.message}`),
        }));
    return { valid: failures.length === 0, failures };
}

/**
 * Check that every edge target resolves to an entity in the bundle.
 *
 * An edge is just an identifier, so a mis-seeded reference produces a syntactically valid
 * entity pointing at nothing. Only references to types the bundle actually contains are
 * checked — a deliberate reference out to an entity generated by a later pass is expected
 * and is reported separately as `external`.
 *
 * @memberof namespace:DataPipeline
 * @function checkEdgeTargets
 * @param {Object.<string, Array<OmcEntity>>} entitiesByType - Entity type to entities
 * @returns {DataPipeline.EdgeCheck} Unresolved references
 */
export function checkEdgeTargets(entitiesByType) {
    const known = new Set();
    for (const entities of Object.values(entitiesByType)) {
        entities.forEach((e) => e.identifier.forEach((i) => known.add(omcIdentifier.idKey(i))));
    }

    const dangling = [];
    const external = {};
    const malformed = [];

    const visit = (source, refs, targetType) => {
        // An edge node that is not a list of references is a finding, not a reason to abort. This
        // is the check that exists to catch bad data, so throwing a TypeError from inside it —
        // which it did, as `refs is not iterable` — failed the whole run at the one moment it was
        // supposed to be explaining what was wrong.
        if (!Array.isArray(refs)) {
            malformed.push({
                from: omcIdentifier.idCombinedForm(source.identifier?.[0] ?? {}, '/'),
                targetType,
                detail: `expected an array of references, found ${
                    refs === null ? 'null' : typeof refs}`,
            });
            return;
        }
        for (const ref of refs) {
            const key = omcIdentifier.idKey(ref.identifier?.[0] ?? {});
            if (known.has(key)) continue;
            if (entitiesByType[targetType]) {
                dangling.push({
                    from: omcIdentifier.idCombinedForm(source.identifier, '/'),
                    targetType,
                    target: key,
                });
            } else {
                external[targetType] = (external[targetType] ?? 0) + 1;
            }
        }
    };

    for (const entities of Object.values(entitiesByType)) {
        for (const entity of entities) {
            for (const byType of Object.values(entity.edges ?? {})) {
                for (const [targetType, refs] of Object.entries(byType)) visit(entity, refs, targetType);
            }
        }
    }
    return { dangling, external, malformed };
}

/**
 * Validate a bundle and check its edges, without writing anything.
 *
 * The checks a bundle must pass before it is fit to leave the process, whether that is to a
 * directory or to a caller over HTTP. Nothing here touches the filesystem, so a service can
 * seal a bundle it never intends to store.
 *
 * @memberof namespace:DataPipeline
 * @function sealBundle
 * @param {Object} params
 * @param {Object.<string, Array<OmcEntity>>} params.entitiesByType - Entity type to entities
 * @returns {{validation: DataPipeline.ValidationResult, edgeCheck: DataPipeline.EdgeCheck, counts: Object.<string, number>}}
 *   Validation, edge check and per-type entity counts
 */
export function sealBundle({ entitiesByType }) {
    const all = Object.values(entitiesByType).flat();
    return {
        validation: validateEntities(all),
        edgeCheck: checkEdgeTargets(entitiesByType),
        counts: Object.fromEntries(
            Object.entries(entitiesByType).map(([entityType, entities]) => [entityType, entities.length]),
        ),
    };
}

/**
 * The message describing a failed validation, naming the first offender.
 *
 * @param {DataPipeline.ValidationResult} validation - The result to describe
 * @param {number} total - How many entities were checked
 * @returns {string} The message
 */
export function validationFailureMessage(validation, total) {
    const [first] = validation.failures;
    return `${validation.failures.length} of ${total} entities failed OMC validation. `
        + `First: ${first.entityType} ${first.identifier} — ${first.errors.join('; ')}`;
}

/**
 * Validate and write an OMC bundle, one file per entity type.
 *
 * Nothing is written unless every entity validates: a half-written bundle that loads
 * without complaint is worse than no bundle.
 *
 * @memberof namespace:DataPipeline
 * @function writeBundle
 * @param {Object} params
 * @param {Object.<string, Array<OmcEntity>>} params.entitiesByType - Entity type to entities
 * @param {string} params.outDir - Directory to write into
 * @returns {Promise<DataPipeline.BundleResult>} Paths written, validation and edge check
 * @throws {Error} When any entity fails validation
 */
export async function writeBundle({ entitiesByType, outDir }) {
    // Loaded on first write rather than at import time. `tabular.js` pulls in ExcelJS, which is
    // several megabytes a caller that only validates never needs — the same reasoning as pdf.js's
    // lazy pdfjs load. It matters: a service imports this module to read the pipeline catalogue,
    // and it should not pay for a spreadsheet writer to do that.
    const { writeJson } = await import('../lib/tabular.js');

    const all = Object.values(entitiesByType).flat();
    const { validation, edgeCheck } = sealBundle({ entitiesByType });

    if (!validation.valid) {
        throw new Error(validationFailureMessage(validation, all.length));
    }

    const written = [];
    for (const [entityType, entities] of Object.entries(entitiesByType)) {
        written.push(await writeJson(path.join(outDir, fileFor(entityType)), entities));
    }
    return { written, validation, edgeCheck };
}
